#include "growth_tactic_lesson_commands.hpp"
#include "growth_tactic_lesson_receipts.hpp"
#include "resident/storage/common_codec.hpp"
#include <tuple>
namespace hanmo::resident {
Outcome<GrowthTacticLessonCommand> decode_growth_tactic_lesson_command(const StableId& kind,const BoundaryValue& params){try{using namespace boundary;const bool start=kind=="tactic_lesson_start";if(!start&&kind!="tactic_lesson_cancel")return {false,{},common_failure("UnsupportedTacticLessonCommand",kind).error};const auto field_name=start?"definition_id":"started_fact_id";fields(params,{field_name},{},kind);if(object(params,kind).size()!=1)fail("InvalidTacticLessonCommand",kind);GrowthTacticLessonCommand out;out.kind=kind;auto value=get_string(params,field_name,kind);if(value.empty()||value.size()>256)fail("InvalidTacticLessonCommand",field_name);if(start)out.definition_id=value;else out.started_fact_id=value;return {true,std::move(out),{}};}catch(const boundary::DecodeFailure& error){return {false,{},error.error};}}
BoundaryValue encode_growth_tactic_lesson_command(const GrowthTacticLessonCommand& c){if(c.kind=="tactic_lesson_start"&&c.started_fact_id.empty())return boundary::obj({{"definition_id",BoundaryValue{c.definition_id}}});if(c.kind=="tactic_lesson_cancel"&&c.definition_id.empty())return boundary::obj({{"started_fact_id",BoundaryValue{c.started_fact_id}}});boundary::fail("InvalidTacticLessonCommand",c.kind);}
Outcome<GrowthTacticLessonCancellationQuote> preview_growth_tactic_lesson_cancellation(const CommonStore& c,const GrowthTacticLessonState& state,const StableId& actor,const StableId& id){
 auto history=validate_growth_tactic_lesson_result_bindings(c,state);if(!history.ok)return {false,{},history.error};const auto* s=state.starts.find(id);const auto* person=c.actor(actor);if(!s||actor!=c.state().metadata.player_actor_id||actor!=s->agreement.student_id||!person||!person->alive||person->action_id!=s->action_id)return {false,{},common_failure("TacticLessonStudentCancellationRequired",id).error};auto payment=release_growth_tactic_lesson_recipe(c,state,id);if(!payment.ok)return {false,{},payment.error};const auto* a=c.action(s->action_id);if(!a||a->remaining_ticks!=s->agreement.duration-payment.value.provided_half_days||c.tick()-s->agreement.tick!=payment.value.provided_half_days)return {false,{},common_failure("TacticLessonStableActionMismatch",id).error};return {true,{c.state().identity,actor,id,s->action_id,payment.value.provided_half_days,payment.value.fee_paid,payment.value.fee_remaining},{}};
}
Status revalidate_growth_tactic_lesson_cancellation(const CommonStore& c,const GrowthTacticLessonState& state,const GrowthTacticLessonCancellationQuote& quote){auto fresh=preview_growth_tactic_lesson_cancellation(c,state,quote.actor_id,quote.started_fact_id);if(!fresh.ok)return {false,{},fresh.error};const auto& a=quote;const auto& b=fresh.value;return std::tie(a.source_identity.world_id,a.source_identity.execution_epoch,a.source_identity.revision,a.source_identity.tick,a.actor_id,a.started_fact_id,a.action_id,a.provided_half_days,a.fee_paid,a.fee_released)==std::tie(b.source_identity.world_id,b.source_identity.execution_epoch,b.source_identity.revision,b.source_identity.tick,b.actor_id,b.started_fact_id,b.action_id,b.provided_half_days,b.fee_paid,b.fee_released)?common_success():common_failure("StaleTacticLessonCancellation",quote.started_fact_id);}
}
